def minDiameterAfterJoin(edges1, edges2):
    from collections import deque

    def diameter(edges):
        n = len(edges) + 1
        if n == 1:
            return 0
        adj = [[] for _ in range(n)]
        for a, b in edges:
            adj[a].append(b)
            adj[b].append(a)

        def far(s):
            dist = [-1] * n
            dist[s] = 0
            q = deque([s])
            last = s
            while q:
                u = q.popleft()
                last = u
                for v in adj[u]:
                    if dist[v] < 0:
                        dist[v] = dist[u] + 1
                        q.append(v)
            return last, dist[last]

        u, _ = far(0)
        return far(u)[1]

    d1, d2 = diameter(edges1), diameter(edges2)
    return max(d1, d2, (d1 + 1) // 2 + (d2 + 1) // 2 + 1)
